<article class="product-card"><a class="product-image" href="/product?slug=<?= e($product['slug']) ?>"><?php if(!empty($product['badge'])): ?><span class="product-badge"><?= e($product['badge']) ?></span><?php endif; ?><img loading="lazy" src="<?= e(product_image($product)) ?>" alt="<?= e($product['name']) ?>"><span class="quick-view">View details ↗</span></a><div class="product-info"><div class="product-category"><?= e($product['category']) ?></div><a class="product-name" href="/product?slug=<?= e($product['slug']) ?>"><?= e($product['name']) ?></a><div class="rating-line"><span class="stars">★★★★★</span><span class="rating-number"><?= number_format((float)$product['rating'],1) ?></span><span class="review-count">(<?= (int)$product['review_count'] ?>)</span></div><div class="price-line"><strong><?= money($product['price']) ?></strong><?php if($product['compare_at'] && $product['compare_at']>$product['price']): ?><del><?= money($product['compare_at']) ?></del><?php endif; ?></div><div class="card-actions"><form method="post" action="/cart/add"><?= csrf_field() ?><input type="hidden" name="product_id" value="<?= (int)$product['id'] ?>"><input type="hidden" name="quantity" value="1"><input type="hidden" name="return_to" value="cart"><button class="btn btn-small btn-primary" <?= (int)$product['stock']<1?'disabled':'' ?>><?= (int)$product['stock']<1?'Out of stock':'Add to cart' ?></button></form><?php if(is_logged_in()): ?><form method="post" action="/wishlist/toggle"><?= csrf_field() ?><input type="hidden" name="product_id" value="<?= (int)$product['id'] ?>"><input type="hidden" name="return_to" value="<?= e($_SERVER['REQUEST_URI']??'/') ?>"><button class="icon-button" title="Save to wishlist" aria-label="Save to wishlist">♡</button></form><?php else: ?><a class="icon-button" href="/sign-in" title="Sign in to save" aria-label="Sign in to save">♡</a><?php endif; ?></div></div></article>